describe('Admin Users & Tenant Management - Member Approval Flow', () => {
  const pendingUser = {
    id: 'p-1',
    userId: 'usr_pending_999',
    email: 'newbie@example.com',
    role: 'unassigned',
    status: 'pending',
    createdAt: '2026-11-18T10:00:00.000Z',
    tenant: null,
  };

  beforeEach(() => {
    cy.intercept('GET', '**/auth/me*', {
      statusCode: 200,
      body: {
        user: {
          username: 'superadmin',
          email: 'admin@platform.com',
        },
      },
    }).as('getCurrentUser');

    cy.intercept('GET', '**/auth/session*', {
      statusCode: 200,
      body: {
        role: 'admin',
        status: 'active',
        tenant: null,
        isImpersonating: false,
      },
    }).as('getAdminSession');
  });

  it('expand member approval form and confirm → provisions tenant and refreshes list', () => {
    cy.intercept('GET', '**/api/admin/users*', {
      statusCode: 200,
      body: { users: [] },
    }).as('getUsers');

    cy.intercept('GET', '**/api/admin/waiting-room*', {
      statusCode: 200,
      body: { pendingUsers: [pendingUser] },
    }).as('getWaitingRoom');

    cy.visit('/users');
    cy.wait('@getUsers');
    cy.wait('@getWaitingRoom');

    cy.contains('.mat-mdc-tab', 'Waiting Room').click();

    // Toggle Member Approval form
    cy.contains('button', 'Approve as Member').click();

    // Form inputs prefilled based on email prefix
    cy.get('input#approvalTenantName_p-1').should('have.value', "newbie's Kitchen");
    cy.get('input#approvalSlug_p-1').should('have.value', 'newbie');

    // Intercept approval request & refresh responses
    cy.intercept('POST', '**/api/admin/users/p-1/approve', {
      statusCode: 200,
      body: { success: true, message: 'Member approved successfully' },
    }).as('approveMember');

    cy.intercept('GET', '**/api/admin/waiting-room*', {
      statusCode: 200,
      body: { pendingUsers: [] },
    }).as('getWaitingRoomCleared');

    cy.contains('button', 'Confirm & Provision Tenant').click();
    cy.wait('@approveMember');

    // Notice alert displayed
    cy.contains('User approved as member and tenant sandbox provisioned successfully!').should(
      'be.visible',
    );

    // Empty state rendered for waiting room
    cy.contains('Waiting room is clear!').should('be.visible');
  });
});

describe('Admin Users & Tenant Management - Impersonation Session', () => {
  const memberUser = {
    id: 'u-2',
    userId: 'usr_member_456',
    email: 'delisha@example.com',
    role: 'member',
    status: 'active',
    createdAt: '2026-02-01T00:00:00.000Z',
    tenant: {
      id: 't-1',
      name: "Delisha's Kitchen",
      slug: 'delisha-kitchen',
      custom_domain: null,
    },
  };

  beforeEach(() => {
    cy.intercept('GET', '**/auth/me*', {
      statusCode: 200,
      body: {
        user: {
          username: 'superadmin',
          email: 'admin@platform.com',
        },
      },
    }).as('getCurrentUser');

    cy.intercept('GET', '**/auth/session*', {
      statusCode: 200,
      body: {
        role: 'admin',
        status: 'active',
        tenant: null,
        isImpersonating: false,
      },
    }).as('getAdminSession');

    cy.intercept('GET', '**/api/admin/users*', {
      statusCode: 200,
      body: { users: [memberUser] },
    }).as('getUsers');

    cy.intercept('GET', '**/api/admin/waiting-room*', {
      statusCode: 200,
      body: { pendingUsers: [] },
    }).as('getWaitingRoom');
  });

  it("click 'Login As' button on member row → launches impersonation session and redirects to /recipes", () => {
    cy.visit('/users');
    cy.wait('@getUsers');
    cy.wait('@getWaitingRoom');

    cy.intercept('POST', '**/api/admin/users/u-2/impersonate', {
      statusCode: 200,
      body: { success: true, message: 'Impersonating' },
    }).as('postImpersonate');

    // Intercept session check triggered after impersonation
    cy.intercept('GET', '**/auth/session*', {
      statusCode: 200,
      body: {
        role: 'member',
        status: 'active',
        tenant: {
          id: 't-1',
          name: "Delisha's Kitchen",
          slug: 'delisha-kitchen',
        },
        isImpersonating: true,
      },
    }).as('getImpersonatedSession');

    cy.intercept('GET', '**/auth/me*', {
      statusCode: 200,
      body: {
        user: {
          username: 'delisha',
          email: 'delisha@example.com',
        },
        adminUser: {
          username: 'superadmin',
          email: 'admin@platform.com',
        },
      },
    }).as('getImpersonatedMe');

    cy.intercept('GET', '**/api/recipes*', {
      statusCode: 200,
      body: [],
    }).as('getRecipes');

    cy.contains('tr', 'delisha@example.com').within(() => {
      cy.contains('button', 'Login As').click();
    });

    cy.wait('@postImpersonate');
    cy.url().should('include', '/recipes');

    // Impersonation banner article is visible (host component uses display: contents)
    cy.get('[aria-label="Active impersonation session"]').should('be.visible');
    cy.contains('Impersonating Member: delisha@example.com').should('be.visible');
    cy.contains("Tenant: Delisha's Kitchen").should('be.visible');
    cy.contains('button', 'Return to Admin').should('be.visible');
  });
});

