describe('Admin Users & Tenant Management - Route Protection Guard', () => {
  it('non-admin member attempts to navigate directly to /users → redirects to /', () => {
    cy.intercept('GET', '**/auth/me*', {
      statusCode: 200,
      body: {
        user: {
          username: 'delisha',
          email: 'delisha@example.com',
        },
      },
    }).as('getMemberUser');

    cy.intercept('GET', '**/auth/session*', {
      statusCode: 200,
      body: {
        role: 'member',
        status: 'active',
        tenant: null,
        isImpersonating: false,
      },
    }).as('getMemberSession');

    cy.intercept('GET', '**/api/home*', {
      statusCode: 200,
      body: {
        totalRecipes: 0,
        recentRecipes: [],
      },
    }).as('getHome');

    cy.visit('/users');

    // authGuard denies access to non-admin and redirects to '/'
    cy.url().should('not.include', '/users');
  });
});
